def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    average_total_charges = sum(values) / len(values)
    return {
        "value": average_total_charges,
        "trace": {
            "total_charges_by_year": values,
            "number_of_years": len(values),
            "average_total_charges": average_total_charges,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": None
            }
        }
    }
